use utf8;
[
{
 id=>"technews", title=>"Teknoloji ve dünya haberleri", emoji=>"🌍", cat=>"Haberler",
 intro=>"{name} bugün okuduğu haberlerden bahsediyor.",
 beats=>[
  { f=>[ ["Did you read the news about the new phone?","Yeni telefonla ilgili haberi okudun mu?"],
         ["Have you seen the news about that new phone everyone is talking about?","Herkesin konuştuğu yeni telefonla ilgili haberi gördün mü?"] ],
    o=>[ [ ["No, tell me about it.","Hayır, anlat bakalım."], ["I have not seen it.","Görmedim."] ],
         [ ["Yes, it is very expensive!","Evet, çok pahalı!"], ["I saw the price. Crazy!","Fiyatını gördüm. Delilik!"] ],
         [ ["I do not change my phone often.","Telefonumu sık değiştirmem."], ["My phone is five years old.","Telefonum beş yaşında."] ] ] },
  { f=>[ ["Everyone talks about artificial intelligence now.","Şimdi herkes yapay zekadan bahsediyor."],
         ["Artificial intelligence is in every headline these days. It is hard to avoid.","Bugünlerde yapay zeka her manşette. Kaçmak zor."] ],
    o=>[ [ ["I use it for studying.","Ders çalışmak için kullanıyorum."], ["I practise English with it.","Onunla İngilizce pratiği yapıyorum."] ],
         [ ["Is it dangerous?","Tehlikeli mi?"], ["Will it take our jobs?","İşlerimizi alacak mı?"] ],
         [ ["I do not understand it well.","Onu pek anlamıyorum."], ["It is new for me.","Benim için yeni."] ] ] },
  { f=>[ ["I think it helps at work, but we must be careful.","Bence işte yardımcı oluyor ama dikkatli olmalıyız."],
         ["It certainly helps at work, though I think we should be careful with it.","İşte kesinlikle yardımcı oluyor ama bence dikkatli olmalıyız."] ],
    o=>[ [ ["That makes sense.","Mantıklı."], ["I think the same.","Ben de öyle düşünüyorum."] ],
         [ ["Do you use it at {work}?","{work} yerinde kullanıyor musun?"], ["Does it help your job?","İşine yardımcı oluyor mu?"] ],
         [ ["I prefer doing things myself.","Ben kendim yapmayı tercih ederim."], ["Old ways are better sometimes.","Bazen eski usul daha iyi."] ] ] },
  { f=>[ ["There was a big story from another country today.","Bugün başka bir ülkeden büyük bir haber vardı."],
         ["There was a serious story from abroad in the headlines today.","Bugün manşetlerde yurt dışından ciddi bir haber vardı."] ],
    o=>[ [ ["What happened?","Ne oldu?"], ["Tell me, I missed it.","Anlat, kaçırmışım."] ],
         [ ["I saw something about that.","Onunla ilgili bir şey gördüm."], ["It was everywhere online.","İnternette her yerdeydi."] ],
         [ ["I try not to read sad news.","Üzücü haberleri okumamaya çalışıyorum."], ["That kind of news worries me.","O tür haberler beni endişelendiriyor."] ] ] },
  { f=>[ ["Do you follow news from other countries?","Başka ülkelerin haberlerini takip eder misin?"],
         ["Do you follow international news, or mainly what happens at home?","Uluslararası haberleri takip eder misin, yoksa daha çok ülkendekileri mi?"] ],
    o=>[ [ ["Only big stories.","Sadece büyük haberleri."], ["Sometimes, not always.","Bazen, her zaman değil."] ],
         [ ["Yes, I read international news.","Evet, uluslararası haber okurum."], ["I follow BBC in English.","BBC'yi İngilizce takip ediyorum."] ],
         [ ["No, only local news.","Hayır, sadece yerel haberler."], ["I care about my city more.","Kendi şehrimi daha çok önemsiyorum."] ] ] },
  { f=>[ ["Reading news in English is good practice, you know.","Haberleri İngilizce okumak iyi bir pratik, biliyor musun?"],
         ["Reading the news in English is one of the best ways to learn, honestly.","Haberleri İngilizce okumak öğrenmenin en iyi yollarından biri, cidden."] ],
    o=>[ [ ["That is a good idea.","İyi fikir."], ["I will start doing that.","Bunu yapmaya başlayacağım."] ],
         [ ["The words are difficult.","Kelimeler zor."], ["News English is hard for me.","Haber İngilizcesi bana zor geliyor."] ],
         [ ["Which website do you recommend?","Hangi siteyi tavsiye edersin?"], ["Where should I start?","Nereden başlamalıyım?"] ] ] },
  { f=>[ ["Start with short articles. Five minutes a day is enough.","Kısa yazılarla başla. Günde beş dakika yeter."],
         ["Start small: one short article a day. Five minutes beats one long hour a month.","Küçük başla: günde bir kısa yazı. Beş dakika, ayda bir saatten iyidir."] ],
    o=>[ [ ["Okay, I will try.","Tamam, deneyeceğim."], ["Five minutes I can do.","Beş dakikayı yapabilirim."] ],
         [ ["Should I use a dictionary?","Sözlük kullanmalı mıyım?"], ["Do I need to know every word?","Her kelimeyi bilmem gerekiyor mu?"] ],
         [ ["I forget the new words.","Yeni kelimeleri unutuyorum."], ["How do you remember words?","Kelimeleri nasıl hatırlıyorsun?"] ] ] },
  { f=>[ ["Write them down. That is what {family} did.","Onları yaz. {family} böyle yaptı."],
         ["Write new words down by hand. That is exactly what {family} did and it worked.","Yeni kelimeleri elle yaz. {family} tam olarak bunu yaptı ve işe yaradı."] ],
    o=>[ [ ["I will buy a notebook.","Bir defter alacağım."], ["Good idea, I will write them.","İyi fikir, yazacağım."] ],
         [ ["I use an app for words.","Kelimeler için uygulama kullanıyorum."], ["My phone has a list.","Telefonumda bir liste var."] ],
         [ ["Ten new words a day?","Günde on yeni kelime?"], ["How many words a day?","Günde kaç kelime?"] ] ] },
  { f=>[ ["Do not rush. Slow and every day is better.","Acele etme. Yavaş ve her gün olması daha iyi."],
         ["Do not rush it. Consistency beats speed every single time.","Acele etme. Süreklilik her zaman hızdan üstündür."] ],
    o=>[ [ ["Thank you for the advice.","Tavsiye için teşekkürler."], ["That helps a lot.","Bu çok yardımcı oldu."] ],
         [ ["Sometimes I want to give up.","Bazen vazgeçmek istiyorum."], ["It is slow progress.","İlerleme yavaş."] ],
         [ ["How long did you learn?","Sen ne kadar sürede öğrendin?"], ["Was it hard for you too?","Senin için de zor muydu?"] ] ] },
  { f=>[ ["You are doing well. Keep going! {phrase}","İyi gidiyorsun. Devam et! {phrase}"],
         ["You are genuinely improving. Do not stop now, that is the important part. {phrase}","Gerçekten gelişiyorsun. Şimdi bırakma, önemli olan bu. {phrase}"] ],
    o=>[ [ ["Thank you, {name}!","Teşekkürler {name}!"], ["That means a lot.","Bu benim için çok değerli."] ],
         [ ["I will practise tomorrow too.","Yarın da pratik yapacağım."], ["Same time tomorrow?","Yarın aynı saatte?"] ],
         [ ["Talking to you helps.","Seninle konuşmak yardımcı oluyor."], ["You are a good teacher.","İyi bir öğretmensin."] ] ] }
 ]
},
{
 id=>"workday", title=>"İş günü", emoji=>"💼", cat=>"İş ve Okul",
 intro=>"{name} ile iş çıkışı konuşuyorsunuz.",
 beats=>[
  { f=>[ ["What a day! I am so tired.","Ne gündü ama! Çok yorgunum."],
