    o=>[ [ ["Was it a busy day?","Yoğun bir gün müydü?"], ["What happened?","Ne oldu?"] ],
         [ ["Sit down and relax.","Otur ve dinlen."], ["You need a break.","Bir molaya ihtiyacın var."] ],
         [ ["My day was long too.","Benim günüm de uzundu."], ["I am tired as well.","Ben de yorgunum."] ] ] },
  { f=>[ ["I work as {job}. Some days are hard.","{job} olarak çalışıyorum. Bazı günler zor."],
         ["Working as {job} is rewarding, but some days really take everything out of you.","{job} olarak çalışmak tatmin edici ama bazı günler insanı tüketiyor."] ],
    o=>[ [ ["How many hours do you work?","Kaç saat çalışıyorsun?"], ["Is it a long day?","Gün uzun mu?"] ],
         [ ["Do you like your colleagues?","İş arkadaşlarını seviyor musun?"], ["Are the people nice there?","Oradaki insanlar iyi mi?"] ],
         [ ["What is the hardest part?","En zor kısmı ne?"], ["What do you like most?","En çok neyi seviyorsun?"] ] ] },
  { f=>[ ["The people at {work} are good. That helps.","{work} yerindeki insanlar iyi. Bu yardımcı oluyor."],
         ["The team at {work} makes a huge difference. Good colleagues change everything.","{work} yerindeki ekip çok fark yaratıyor. İyi iş arkadaşları her şeyi değiştirir."] ],
    o=>[ [ ["That is important.","Bu önemli."], ["Good people make a difference.","İyi insanlar fark yaratır."] ],
         [ ["My colleagues are okay.","Benim iş arkadaşlarım idare eder."], ["I work alone mostly.","Çoğunlukla yalnız çalışıyorum."] ],
         [ ["Do you see them outside work?","Onları iş dışında görüyor musun?"], ["Are they your friends too?","Aynı zamanda arkadaşın mılar?"] ] ] },
  { f=>[ ["What do you do for work?","Sen ne iş yapıyorsun?"],
         ["Tell me about your job. What do you actually do all day?","Bana işinden bahset. Gün boyu tam olarak ne yapıyorsun?"] ],
    o=>[ [ ["I work in an office.","Bir ofiste çalışıyorum."], ["I am a student.","Öğrenciyim."] ],
         [ ["I work with computers.","Bilgisayarlarla çalışıyorum."], ["I work in a shop.","Bir mağazada çalışıyorum."] ],
         [ ["I am looking for a job.","İş arıyorum."], ["I am between jobs right now.","Şu an işsizim."] ] ] },
  { f=>[ ["Do you like it? That is the important question.","Seviyor musun? Asıl önemli soru bu."],
         ["But do you actually enjoy it? That is the question nobody asks.","Ama gerçekten seviyor musun? Kimsenin sormadığı soru bu."] ],
    o=>[ [ ["Yes, most days.","Evet, çoğu gün."], ["I like it, yes.","Evet, seviyorum."] ],
         [ ["Not really, it is just money.","Pek değil, sadece para için."], ["It pays the bills.","Faturaları ödüyor."] ],
         [ ["I want to change job.","İş değiştirmek istiyorum."], ["I am thinking about it.","Düşünüyorum."] ] ] },
  { f=>[ ["Change is scary but good. I changed twice.","Değişim korkutucu ama iyi. Ben iki kez değiştirdim."],
         ["Changing career is frightening, but I have done it twice and never regretted it.","Kariyer değiştirmek ürkütücü ama iki kez yaptım ve hiç pişman olmadım."] ],
    o=>[ [ ["Really? What did you do before?","Gerçekten mi? Önce ne yapıyordun?"], ["Tell me the story.","Hikayeyi anlat."] ],
         [ ["Was it difficult?","Zor muydu?"], ["Were you afraid?","Korktun mu?"] ],
         [ ["Maybe I need courage.","Belki cesarete ihtiyacım var."], ["I am afraid of change.","Değişimden korkuyorum."] ] ] },
  { f=>[ ["Money is not everything. Time matters too.","Para her şey değil. Zaman da önemli."],
         ["A bigger salary is nice, but time and health matter far more in the end.","Yüksek maaş güzel ama sonunda zaman ve sağlık çok daha önemli."] ],
    o=>[ [ ["You are right.","Haklısın."], ["I need to remember that.","Bunu hatırlamam lazım."] ],
         [ ["But I need money too!","Ama benim de paraya ihtiyacım var!"], ["Bills do not pay themselves.","Faturalar kendi kendine ödenmiyor."] ],
         [ ["Do you work at weekends?","Hafta sonu çalışıyor musun?"], ["Do you have free time?","Boş vaktin var mı?"] ] ] },
  { f=>[ ["I do {hobby} to relax. It really helps.","Rahatlamak için {hobby} yapıyorum. Çok yardımcı oluyor."],
         ["My way of switching off is {hobby}. Without it I would go mad.","Kafayı dağıtma yöntemim {hobby}. O olmasa delirirdim."] ],
    o=>[ [ ["That sounds relaxing.","Kulağa rahatlatıcı geliyor."], ["I should try that.","Bunu denemeliyim."] ],
         [ ["I relax by watching TV.","Ben televizyon izleyerek rahatlıyorum."], ["I go for walks.","Yürüyüşe çıkıyorum."] ],
         [ ["I do not have a hobby.","Benim hobim yok."], ["I never have free time.","Hiç boş vaktim olmuyor."] ] ] },
  { f=>[ ["Everyone needs one thing just for themselves.","Herkesin sadece kendisi için bir şeye ihtiyacı var."],
         ["Everybody needs one thing that belongs only to them, not to work or family.","Herkesin sadece kendine ait, ne işe ne aileye ait olmayan bir şeye ihtiyacı var."] ],
    o=>[ [ ["That is true.","Bu doğru."], ["I will find something.","Bir şey bulacağım."] ],
         [ ["Maybe learning English is mine!","Belki benimki İngilizce öğrenmek!"], ["This is my hobby now.","Bu artık benim hobim."] ],
         [ ["What do you recommend?","Ne tavsiye edersin?"], ["Any ideas for me?","Bana bir fikrin var mı?"] ] ] },
  { f=>[ ["Right, I am going home to sleep. {phrase}","Tamam, eve uyumaya gidiyorum. {phrase}"],
         ["Anyway, I am going home to collapse on the sofa. {phrase}","Neyse, eve gidip kanepeye yığılacağım. {phrase}"] ],
