         [ ["See you tomorrow.","Yarın görüşürüz."], ["Same time tomorrow?","Yarın aynı saatte?"] ],
         [ ["Thanks for the chat.","Sohbet için teşekkürler."], ["That was nice, {name}.","Güzeldi {name}."] ] ] }
 ]
