{
 id=>"weekend", title=>"Hafta sonu planı", emoji=>"🎉", cat=>"Günlük Hayat",
 intro=>"Cuma akşamı, {name} hafta sonu planı yapıyor.",
 beats=>[
  { f=>[ ["It is Friday! What are you doing this weekend?","Cuma oldu! Bu hafta sonu ne yapıyorsun?"],
         ["Finally Friday. Have you got any plans for the weekend, or is it open?","Nihayet cuma. Hafta sonu için planın var mı, yoksa boş mu?"] ],
    o=>[ [ ["Nothing special.","Özel bir şey yok."], ["I have no plans yet.","Henüz planım yok."] ],
         [ ["I am seeing my family.","Ailemi göreceğim."], ["I am visiting my parents.","Anne babamı ziyaret edeceğim."] ],
         [ ["I am working, sadly.","Ne yazık ki çalışıyorum."], ["I work on Saturday.","Cumartesi çalışıyorum."] ] ] },
  { f=>[ ["Come with me then! I am going out on Saturday.","O zaman benimle gel! Cumartesi dışarı çıkıyorum."],
         ["In that case, come with us on Saturday. There will be a few of us.","O zaman cumartesi bizimle gel. Birkaç kişi olacağız."] ],
    o=>[ [ ["Where are you going?","Nereye gidiyorsunuz?"], ["What is the plan?","Plan ne?"] ],
         [ ["Yes, I would love to!","Evet, çok isterim!"], ["Count me in!","Ben varım!"] ],
         [ ["Who else is coming?","Başka kim geliyor?"], ["Will I know anyone?","Tanıdığım biri olacak mı?"] ] ] },
  { f=>[ ["We are going to a place with live {music}.","Canlı {music} olan bir yere gidiyoruz."],
         ["There is a small place near me with live {music} on Saturdays. It is brilliant.","Yakınımda cumartesileri canlı {music} olan küçük bir yer var. Harika."] ],
    o=>[ [ ["I love that music!","O müziğe bayılırım!"], ["That sounds fun.","Kulağa eğlenceli geliyor."] ],
         [ ["I do not know that music.","O müziği bilmiyorum."], ["Is it loud?","Gürültülü mü?"] ],
         [ ["What time does it start?","Saat kaçta başlıyor?"], ["How late does it finish?","Ne kadar geç bitiyor?"] ] ] },
  { f=>[ ["Nine o'clock. Do not be late, please!","Saat dokuz. Lütfen geç kalma!"],
         ["It kicks off at nine. And please, for once, do not be fashionably late.","Dokuzda başlıyor. Ve lütfen bir kez olsun geç kalma."] ],
    o=>[ [ ["I will be there at nine.","Dokuzda orada olacağım."], ["I am never late!","Ben hiç geç kalmam!"] ],
         [ ["I might be a little late.","Biraz geç kalabilirim."], ["I finish work at eight.","İşim sekizde bitiyor."] ],
         [ ["Where do we meet?","Nerede buluşuyoruz?"], ["Send me the address.","Adresi bana gönder."] ] ] },
  { f=>[ ["On Sunday I usually do {hobby}.","Pazar günleri genelde {hobby} yaparım."],
         ["Sundays are sacred for me. That is when I do {hobby} and nothing else.","Pazarlar benim için kutsal. O gün {hobby} yaparım, başka bir şey yok."] ],
    o=>[ [ ["Every Sunday?","Her pazar mı?"], ["Do you never miss it?","Hiç kaçırmaz mısın?"] ],
         [ ["Can I come with you?","Seninle gelebilir miyim?"], ["Can I try it?","Deneyebilir miyim?"] ],
         [ ["I sleep all Sunday!","Ben bütün pazar uyurum!"], ["Sunday is my lazy day.","Pazar benim tembellik günüm."] ] ] },
  { f=>[ ["Of course you can come! It is more fun with two.","Tabii ki gelebilirsin! İki kişi daha eğlenceli."],
         ["Of course, come along. Everything is better with company anyway.","Tabii ki gel. Zaten her şey birlikte daha güzel."] ],
    o=>[ [ ["Great! What do I need?","Harika! Neye ihtiyacım var?"], ["What should I bring?","Ne getirmeliyim?"] ],
         [ ["I am not very good at it.","Bunda pek iyi değilim."], ["I have never done it.","Hiç yapmadım."] ],
         [ ["What time on Sunday?","Pazar saat kaçta?"], ["Morning or afternoon?","Sabah mı öğleden sonra mı?"] ] ] },
  { f=>[ ["Just bring yourself. I have everything.","Sadece kendini getir. Bende her şey var."],
         ["Bring nothing but yourself and a good mood. I have everything else.","Kendinden ve iyi bir keyiften başka bir şey getirme. Gerisi bende."] ],
    o=>[ [ ["Perfect. Thank you!","Mükemmel. Teşekkürler!"], ["That is easy then.","O zaman kolay."] ],
         [ ["I will bring some food.","Ben biraz yemek getiririm."], ["I will bring drinks.","İçecek getiririm."] ],
         [ ["I am excited!","Heyecanlandım!"], ["I am looking forward to it.","Sabırsızlanıyorum."] ] ] },
  { f=>[ ["What do you usually do at weekends?","Sen hafta sonları genelde ne yaparsın?"],
         ["Tell me about your weekends. What does a normal Saturday look like for you?","Hafta sonlarını anlat. Senin için normal bir cumartesi nasıl geçer?"] ],
    o=>[ [ ["I stay at home and rest.","Evde kalıp dinlenirim."], ["I clean the house.","Ev temizliği yaparım."] ],
         [ ["I meet friends.","Arkadaşlarla buluşurum."], ["I go out with my family.","Ailemle dışarı çıkarım."] ],
         [ ["I study English.","İngilizce çalışırım."], ["I watch films all day.","Bütün gün film izlerim."] ] ] },
  { f=>[ ["You need to get out more! Life is short.","Daha çok dışarı çıkmalısın! Hayat kısa."],
         ["You should get out more, honestly. The weeks disappear if you are not careful.","Cidden daha çok dışarı çıkmalısın. Dikkat etmezsen haftalar uçup gidiyor."] ],
    o=>[ [ ["You are probably right.","Muhtemelen haklısın."], ["I know, I know.","Biliyorum, biliyorum."] ],
         [ ["I am a bit shy.","Biraz utangacım."], ["I do not know many people here.","Burada çok kişi tanımıyorum."] ],
         [ ["That is why I have you!","İşte bu yüzden sen varsın!"], ["You are my social life.","Sosyal hayatım sensin."] ] ] },
  { f=>[ ["See you Saturday at nine! {phrase}","Cumartesi dokuzda görüşürüz! {phrase}"],
         ["Saturday, nine o'clock, no excuses. It is going to be a good one. {phrase}","Cumartesi, saat dokuz, bahane yok. Güzel geçecek. {phrase}"] ],
    o=>[ [ ["See you then!","O zaman görüşürüz!"], ["I will be there!","Orada olacağım!"] ],
         [ ["Message me before.","Öncesinde mesaj at."], ["Remind me on Saturday.","Cumartesi hatırlat."] ],
         [ ["Have a good Friday night!","İyi cumalar!"], ["Enjoy your evening.","İyi akşamlar."] ] ] }
 ]
