{
 id=>"shopping", title=>"Alışverişte", emoji=>"🛒", cat=>"Günlük Hayat",
 intro=>"{name} ile alışveriş yapıyorsunuz.",
 beats=>[
  { f=>[ ["I need a few things. Come with me?","Birkaç şey lazım. Benimle gelir misin?"],
         ["I only need a few bits, but shopping alone is miserable. Come with me?","Sadece birkaç şey lazım ama tek başına alışveriş berbat. Benimle gelir misin?"] ],
    o=>[ [ ["Sure, I have time.","Tabii, vaktim var."], ["Yes, let us go.","Evet, gidelim."] ],
         [ ["What do you need to buy?","Ne alman lazım?"], ["Do you have a list?","Listen var mı?"] ],
         [ ["I need things too.","Benim de bir şeylere ihtiyacım var."], ["Good, I need bread and milk.","İyi, benim de ekmek ve süt lazım."] ] ] },
  { f=>[ ["I always forget my list at home!","Listemi hep evde unutuyorum!"],
         ["I have written a list and, naturally, left it on the kitchen table.","Liste yazdım ve tabii ki mutfak masasında unuttum."] ],
    o=>[ [ ["Try to remember!","Hatırlamaya çalış!"], ["What was on it?","Listede ne vardı?"] ],
         [ ["I keep mine on my phone.","Ben listemi telefonumda tutuyorum."], ["Use your phone next time.","Bir dahaki sefere telefonunu kullan."] ],
         [ ["We will remember together.","Beraber hatırlarız."], ["Do not worry about it.","Boş ver."] ] ] },
  { f=>[ ["Look at these prices! Everything is more expensive.","Şu fiyatlara bak! Her şey daha pahalı."],
         ["Look at this. The same shopping cost me far less last year.","Şuna bak. Aynı alışveriş geçen yıl çok daha ucuzdu."] ],
    o=>[ [ ["Yes, it is very expensive.","Evet, çok pahalı."], ["I noticed that too.","Ben de fark ettim."] ],
         [ ["Which shop is cheaper?","Hangi mağaza daha ucuz?"], ["Do you know a cheap place?","Ucuz bir yer biliyor musun?"] ],
         [ ["I buy only what I need.","Sadece ihtiyacım olanı alıyorum."], ["I never buy extra now.","Artık fazladan bir şey almıyorum."] ] ] },
  { f=>[ ["I always buy the things for {breakfast} first.","Önce hep {breakfast} için gerekenleri alırım."],
         ["My basket is always the same: everything for {breakfast}, then the rest.","Sepetim hep aynı: önce {breakfast} için her şey, sonra gerisi."] ],
    o=>[ [ ["You really love that breakfast!","O kahvaltıyı gerçekten seviyorsun!"], ["Every day the same?","Her gün aynı mı?"] ],
         [ ["I buy eggs and cheese.","Ben yumurta ve peynir alıyorum."], ["Bread and tea for me.","Bana ekmek ve çay."] ],
         [ ["Where is the bread here?","Ekmek burada nerede?"], ["Which aisle is the milk?","Süt hangi reyonda?"] ] ] },
  { f=>[ ["I need new shoes as well. What do you think of these?","Yeni ayakkabı da lazım. Bunlar hakkında ne düşünüyorsun?"],
         ["While we are here, I need shoes. Be honest, what do you think of these?","Hazır gelmişken ayakkabı lazım. Dürüst ol, bunlar nasıl?"] ],
    o=>[ [ ["They look good!","Güzel görünüyorlar!"], ["I like them.","Beğendim."] ],
         [ ["Not really my style.","Pek benim tarzım değil."], ["Try the black ones.","Siyah olanları dene."] ],
         [ ["How much are they?","Kaç para?"], ["Are they comfortable?","Rahat mı?"] ] ] },
  { f=>[ ["Too expensive. I will wait for the sale.","Çok pahalı. İndirimi bekleyeceğim."],
         ["That is far too much. I will wait for the sales in January.","Bu çok fazla. Ocaktaki indirimleri bekleyeceğim."] ],
    o=>[ [ ["Good idea. Be patient.","İyi fikir. Sabırlı ol."], ["Sales are always better.","İndirimler hep daha iyi."] ],
         [ ["But you like them a lot!","Ama onları çok beğendin!"], ["Buy them, you deserve it.","Al onları, hak ediyorsun."] ],
         [ ["I never buy full price.","Ben hiç tam fiyata almam."], ["I always look online first.","Önce hep internete bakarım."] ] ] },
  { f=>[ ["Do you shop online or in real shops?","İnternetten mi alışveriş yaparsın yoksa gerçek mağazadan mı?"],
         ["Are you an online shopper, or do you prefer actually going into shops?","İnternetten mi alışveriş yaparsın, yoksa mağazaya gitmeyi mi seversin?"] ],
    o=>[ [ ["Online, it is easier.","İnternetten, daha kolay."], ["I buy everything online.","Her şeyi internetten alıyorum."] ],
         [ ["Real shops. I like to see things.","Gerçek mağaza. Görmeyi severim."], ["I need to try clothes on.","Kıyafetleri denemem gerekiyor."] ],
         [ ["Both, it depends.","İkisi de, duruma göre."], ["Food in shops, clothes online.","Yemeği mağazadan, kıyafeti internetten."] ] ] },
  { f=>[ ["The queue is so long. We will be here forever.","Kuyruk çok uzun. Sonsuza kadar burada olacağız."],
         ["Look at that queue. We are going to be standing here for twenty minutes.","Şu kuyruğa bak. Yirmi dakika burada dikileceğiz."] ],
    o=>[ [ ["Let us use the self checkout.","Self servis kasayı kullanalım."], ["Try the other till.","Diğer kasayı dene."] ],
         [ ["It is okay, we can talk.","Sorun değil, konuşuruz."], ["I do not mind waiting.","Beklemek sorun değil."] ],
         [ ["I hate queues!","Kuyruklardan nefret ederim!"], ["This is my worst nightmare.","Bu benim en büyük kabusum."] ] ] },
  { f=>[ ["Can you carry one bag? Thank you!","Bir poşet taşıyabilir misin? Teşekkürler!"],
         ["Would you take one of these bags? I have somehow bought far too much.","Şu poşetlerden birini alır mısın? Bir şekilde çok fazla şey almışım."] ],
    o=>[ [ ["Of course, give me two.","Tabii, iki tane ver."], ["No problem at all.","Hiç sorun değil."] ],
         [ ["They are heavy!","Ağırlar!"], ["What did you buy, rocks?","Ne aldın, taş mı?"] ],
         [ ["Where is your car?","Araban nerede?"], ["How do we get home?","Eve nasıl gideceğiz?"] ] ] },
  { f=>[ ["Thanks for coming. Shopping alone is boring. {phrase}","Geldiğin için sağ ol. Tek başına alışveriş sıkıcı. {phrase}"],
         ["Thank you for coming, genuinely. Shopping alone is the worst job in the world. {phrase}","Geldiğin için cidden sağ ol. Tek başına alışveriş dünyanın en kötü işi. {phrase}"] ],
    o=>[ [ ["Any time!","Ne zaman istersen!"], ["It was fun.","Eğlenceliydi."] ],
         [ ["Now I need coffee.","Şimdi bana kahve lazım."], ["Shall we sit down somewhere?","Bir yerde oturalım mı?"] ],
         [ ["Call me next time too.","Bir dahaki sefere de beni ara."], ["See you soon!","Yakında görüşürüz!"] ] ] }
 ]
},
{
 id=>"health", title=>"Sağlık ve doktor", emoji=>"🏥", cat=>"Sağlık",
 intro=>"{name} kendini iyi hissetmiyor.",
 beats=>[
  { f=>[ ["I do not feel well today.","Bugün kendimi iyi hissetmiyorum."],
         ["I have not felt right since yesterday. Something is definitely wrong.","Dünden beri kendimi iyi hissetmiyorum. Kesin bir şey var."] ],
    o=>[ [ ["What is wrong?","Neyin var?"], ["Are you okay?","İyi misin?"] ],
         [ ["Do you have a temperature?","Ateşin var mı?"], ["Do you feel hot or cold?","Sıcak mı soğuk mu hissediyorsun?"] ],
         [ ["Sit down. I will get water.","Otur. Ben su getireyim."], ["Do you need anything?","Bir şeye ihtiyacın var mı?"] ] ] },
  { f=>[ ["I have a headache and a sore throat.","Başım ağrıyor ve boğazım yanıyor."],
         ["My head is pounding and my throat feels like sandpaper.","Başım zonkluyor ve boğazım zımpara gibi."] ],
    o=>[ [ ["You should rest.","Dinlenmelisin."], ["Go home and sleep.","Eve git ve uyu."] ],
         [ ["Did you take medicine?","İlaç aldın mı?"], ["Have you got any tablets?","Hapın var mı?"] ],
         [ ["Drink hot tea with lemon.","Limonlu sıcak çay iç."], ["Honey helps a lot.","Bal çok iyi gelir."] ] ] },
  { f=>[ ["I hate going to the doctor.","Doktora gitmekten nefret ediyorum."],
         ["I really do not want to see a doctor. I never have, even as a child.","Doktora gitmeyi hiç istemiyorum. Çocukken bile istemezdim."] ],
    o=>[ [ ["But you must go!","Ama gitmelisin!"], ["Health comes first.","Sağlık her şeyden önce gelir."] ],
         [ ["I understand. Me too.","Anlıyorum. Ben de öyle."], ["Doctors make me nervous.","Doktorlar beni geriyor."] ],
         [ ["I can come with you.","Seninle gelebilirim."], ["Do not go alone.","Yalnız gitme."] ] ] },
  { f=>[ ["Maybe you are right. I will call tomorrow.","Belki haklısın. Yarın ararım."],
         ["Fine, you win. I will phone the surgery first thing tomorrow.","Tamam, sen kazandın. Yarın ilk iş kliniği ararım."] ],
    o=>[ [ ["Good! Do not forget.","Güzel! Unutma."], ["Promise me.","Bana söz ver."] ],
         [ ["What time do they open?","Kaçta açılıyorlar?"], ["Do you need an appointment?","Randevu gerekiyor mu?"] ],
         [ ["Text me after.","Sonra bana yaz."], ["Tell me what they say.","Ne dediklerini söyle."] ] ] },
  { f=>[ ["Are you healthy? Do you do sport?","Sen sağlıklı mısın? Spor yapıyor musun?"],
         ["What about you, are you looking after yourself? Any exercise?","Peki ya sen, kendine iyi bakıyor musun? Spor var mı?"] ],
    o=>[ [ ["I walk every day.","Her gün yürüyorum."], ["I try to walk a lot.","Çok yürümeye çalışıyorum."] ],
         [ ["I go to the gym twice a week.","Haftada iki kez spor salonuna gidiyorum."], ["I run at weekends.","Hafta sonları koşuyorum."] ],
         [ ["No, I sit all day.","Hayır, bütün gün oturuyorum."], ["I should do more.","Daha fazla yapmalıyım."] ] ] },
  { f=>[ ["Sitting all day is bad. Even ten minutes helps.","Bütün gün oturmak kötü. On dakika bile fayda eder."],
         ["Sitting for hours is genuinely bad for you. Even ten minutes of walking helps.","Saatlerce oturmak cidden zararlı. On dakikalık yürüyüş bile iyi gelir."] ],
    o=>[ [ ["I will start walking.","Yürümeye başlayacağım."], ["Ten minutes I can do.","On dakikayı yapabilirim."] ],
         [ ["I am too tired after work.","İşten sonra çok yorgun oluyorum."], ["I have no energy.","Enerjim yok."] ],
         [ ["Do you exercise?","Sen spor yapıyor musun?"], ["What do you do to stay fit?","Formda kalmak için ne yapıyorsun?"] ] ] },
  { f=>[ ["I do {hobby}, and I walk to {work}.","{hobby} yapıyorum ve {work} yerine yürüyorum."],
         ["Between {hobby} and walking to {work}, I move more than I think.","{hobby} ve {work} yerine yürümek arasında sandığımdan çok hareket ediyorum."] ],
    o=>[ [ ["That is a good routine.","İyi bir rutin."], ["Small things add up.","Küçük şeyler birikiyor."] ],
         [ ["How far do you walk?","Ne kadar yürüyorsun?"], ["How long does it take?","Ne kadar sürüyor?"] ],
         [ ["I drive everywhere.","Ben her yere arabayla giderim."], ["I take the bus, always.","Hep otobüse binerim."] ] ] },
  { f=>[ ["Sleep is important too. I need eight hours.","Uyku da önemli. Bana sekiz saat lazım."],
         ["Sleep matters more than people admit. I am useless with less than eight hours.","Uyku insanların kabul ettiğinden önemli. Sekiz saatten az uyursam işe yaramam."] ],
    o=>[ [ ["I sleep six hours.","Ben altı saat uyuyorum."], ["I never sleep enough.","Hiç yeterince uyuyamıyorum."] ],
         [ ["I sleep well, luckily.","Şansıma iyi uyuyorum."], ["I sleep like a stone.","Taş gibi uyurum."] ],
         [ ["My phone keeps me awake.","Telefon beni uyutmuyor."], ["I go to bed too late.","Çok geç yatıyorum."] ] ] },
  { f=>[ ["Put the phone away one hour before bed. It works.","Yatmadan bir saat önce telefonu bırak. İşe yarıyor."],
         ["Try leaving your phone in another room an hour before bed. It genuinely works.","Yatmadan bir saat önce telefonu başka odaya bırakmayı dene. Cidden işe yarıyor."] ],
    o=>[ [ ["I will try tonight.","Bu gece deneyeceğim."], ["That is hard but okay.","Zor ama tamam."] ],
         [ ["I use my phone as an alarm.","Telefonu alarm olarak kullanıyorum."], ["Then I need a real clock.","O zaman gerçek bir saat lazım."] ],
         [ ["Do you do that?","Sen böyle yapıyor musun?"], ["Does it really help?","Gerçekten yardımcı oluyor mu?"] ] ] },
  { f=>[ ["Look after yourself. I need you healthy! {phrase}","Kendine iyi bak. Sağlıklı olmana ihtiyacım var! {phrase}"],
         ["Look after yourself properly. I would like to keep you around a while. {phrase}","Kendine düzgün bak. Seni bir süre daha yanımda tutmak isterim. {phrase}"] ],
    o=>[ [ ["You too! Get well soon.","Sen de! Geçmiş olsun."], ["Take your medicine!","İlacını iç!"] ],
         [ ["Thank you for caring.","İlgin için teşekkürler."], ["That is kind of you.","Çok naziksin."] ],
         [ ["Call me if you need anything.","Bir şeye ihtiyacın olursa ara."], ["I am here for you.","Senin için buradayım."] ] ] }
 ]
}
